{{-- Mesajdakı fayl ($f — SupportMessage::toChat()['file']): şəkil və video söhbətdə görünür (video oynadılır, böyük ekranda da açılır), qalanı yüklənir. Brauzerdəki eynisi: support-chat.js → fileEl --}}
@if ($f['image'])<a href="{{ $f['url'] }}" class="chat-file-img" target="_blank" rel="noopener"><img src="{{ $f['url'] }}" alt="{{ $f['name'] }}" loading="lazy"></a>@elseif ($f['video'] ?? false)<div class="chat-file-video"><video src="{{ $f['url'] }}" controls playsinline preload="metadata"></video><button type="button" class="chat-video-full" aria-label="Böyük ekranda aç"><i class="fa fa-expand"></i></button></div>@else<a href="{{ $f['url'] }}" class="chat-file" download="{{ $f['name'] }}"><i class="fa fa-file-alt"></i><span class="chat-file-name">{{ $f['name'] }}</span><small>{{ $f['size'] }}</small></a>@endif
